	void dispose() {
		disposed = true;
		projectData.removeDomainFolderChangeListener(this);
		initialIndexFuture.cancel(false);
		lock (openedForUpdate) {
			foreach (ModuleChangeListener listener in openedForUpdate.values()) {
				listener.dispose();
			}
			openedForUpdate.clear();
		}
	}

